  const title=tower?'空の中継塔':'霧の関所',image=tower?'sky-tower':'mist-gate',person=tower?'sky-keeper':'mist-keeper';
  const role=tower?'知らせをつなぐ中継係':'旅人と知らせを迎える関所の守り手';
  const line=tower?'ようこそ、僕はアルト。塔の合図を預かっているよ。届かない知らせがあってね、一緒に道を調べてくれる？':'私はシノ。ここでは人と知らせを迎えているの。送った覚えのない知らせが届いたそうよ。一緒に確かめましょう。';
