  app.querySelectorAll('[data-tg-quest]').forEach(b=>b.onclick=()=>{state.towerGateActive=b.dataset.tgQuest;state.towerGateDrafts??={};state.towerGateDrafts[state.towerGateActive]??=[];show('tower-gate-quest');});
  if(tower&&state.storyClimaxComplete&&festivalReady(state.completed)){const section=document.createElement('section');section.className='panel';section.innerHTML=`<h2>塔に届いた新しい依頼</h2><p>宛先と、知らせを送る順番を確かめましょう。</p><div class="actions"><button id="name-lab">名前から宛先を調べる${state.completed.includes('tower-name-lab')?'（達成済み）':''}</button><button id="queue-lab">塔の送信口を手伝う${state.completed.includes('tower-queue-lab')?'（達成済み）':''}</button></div>`;app.querySelector('h2').before(section);section.querySelector('#name-lab').onclick=()=>{state.nameHistory??=[];show('tower-name-lab');};section.querySelector('#queue-lab').onclick=()=>{state.queueHistory??=[];show('tower-queue-lab');};}
  if(!tower&&state.storyClimaxComplete&&festivalReady(state.completed)){const section=document.createElement('section');section.className='panel';section.innerHTML=`<h2>関所に届いた新しい依頼</h2><p>大切な帳面を守る仕掛けを確かめましょう。</p><div class="actions"><button id="access-lab">本人確認と権限を確かめる${state.completed.includes('gate-access-lab')?'（達成済み）':''}</button><button id="paths-lab">二つの入口を確かめる${state.completed.includes('gate-paths-lab')?'（達成済み）':''}</button></div>`;app.querySelector('h2').before(section);section.querySelector('#access-lab').onclick=()=>{state.accessHistory??=[];show('gate-access-lab');};section.querySelector('#paths-lab').onclick=()=>{state.pathsHistory??=[];show('gate-paths-lab');};}
  app.querySelector('#milestone')?.addEventListener('click',()=>{state.towerGateSeen=true;show('tower-gate-ending');});
  app.querySelector('#travel').onclick=()=>show('travel');
