 app.querySelector('#four-undo').onclick=()=>{state.fourDrafts[id]=draft.slice(0,-1);state.fourSelections[id]=[];persist();fourQuest();app.querySelector('#four-status').focus({preventScroll:true});};app.querySelector('#four-back').onclick=()=>show(q.region);
