const finalePeople={workshop:['lira','工房から始まった旅が、こんなに広がったのね。'],river:['mizuho','川の向こうのみんなにも、この知らせを届けたいな。'],city:['mina','街のギルドからも、みんなの旅を応援するよ！'],harbor:['ren','港へ届いた知らせは、僕が次の人へ渡すよ！'],archive:['aoi','道がつながると、本もいろんな人に届けられるわね。'],windmill:['toma','旅の道具に困ったら、いつでも里へおいで。'],mountain:['sora','山道のことなら任せて。安心して通れる道を知らせるよ。'],valley:['yuno','届け先の記録は私が預かるわ。大切な荷物をつなぎましょう。'],sky:['alto','塔からも、みんなの知らせをつないでいくよ！'],mist:['shino','関所でも旅人を迎えるわ。道中、気をつけてね。'],forge:['akari','道具に困ったときは、鍛冶街にも声をかけてね。'],station:['haru','駅でもみんなの荷物を待っているよ。'],garden:['nagi','庭の花が咲いたら、みんなにも見に来てほしいな。'],observatory:['sena','空の様子も知らせるね。旅の日が晴れるといいな！'],tailor:['dario','旅の支度が必要なら、いつでも話を聞かせておくれ。'],guide:['marta','初めての土地でも、安心して歩けるように案内するわ。']};
function finaleNotice(){
 if(!state||state.place==='world-finale'||!unlocked(state.completed))return;
 const places=['choices','river','city','harbor','mid-archive','mid-windmill','mountain','valley','sky','mist','forge','station',...fourRegionIds,'travel'];
 if(!places.includes(state.place))return;
 const progress=worldRegionProgress(state.completed),ready=worldFinaleReady(state.completed);
 const section=document.createElement('section');section.className='panel story-progress';
 const visible=new Set(availableTravelPlaces(state).map(p=>p.id));
 const names=storyRegions.filter(id=>visible.has(id)).map(id=>travelPlaces.find(p=>p.id===id)).filter(Boolean);
 const helpedCount=storyRegions.filter(id=>progress[id]===2).length;
 const rumor=helpedCount<4?'旅人から、道しるべの向きが古いままの場所があると聞きました。':helpedCount<8?'別の土地からも、待っている手紙がなかなか届かないという話が聞こえてきました。':'各地の道しるべや配達の行き違いが重なっているようです。仲間と話を集め、力を合わせる準備をしましょう。';
 section.innerHTML=`<h2>各地をつなぐ知らせ</h2>${ready?`<p>${state.storyClimaxComplete?'みんなで届けた知らせを振り返れます。':'各地の仲間から集いへの知らせが届きました。好きなときに向かえます。'}</p><button id="world-finale-open">集いへ向かう</button>`:`<p>${rumor} 12の土地それぞれで二つのお手伝いをしましょう。</p><details><summary>お手伝いが二つ終わった地域（${helpedCount} / 12）</summary><ul>${names.map(p=>`<li>${p.name}：${progress[p.id]} / 2 件</li>`).join('')}</ul><p>まだ知らせの届いていない土地もあります。</p></details>`}`;
 app.append(section);section.querySelector('#world-finale-open')?.addEventListener('click',()=>{state.worldFinaleFrom=state.place;state.storyClimaxHistory??=[];state.storyClimaxComplete??=false;show('world-finale');});
}
function worldFinale(){
 const history=state.storyClimaxHistory??[],step=climaxSteps[history.length],done=climaxComplete(history),quest=step?.quest??3;
 const heading=['','手紙の道筋をたどる','中継所から手紙を運ぶ','手紙を本人に届ける'][quest];
 const lesson=['','時刻つきの記録を使うと、出来事の順序をたどれます。通信でも、途中の場所が次の送り先を決めて情報を届けます。','二人が同じ道具を使うときは、使う順番を調整し、使い終えてから次の人に渡します。コンピュータでも仕事の順番と共有する資源の管理が必要です。','本人が使いやすい方法を尋ねることと、本人かどうか確かめることは別の役目です。事前に共有した秘密を人目に触れずに確かめ、両方を大切にします。'][quest];
 const mapChoice=history.length===3||history.length===4;
 const mapAction=(id,label)=>mapChoice&&step.choices.some(([choice])=>choice===id)?`role="button" tabindex="0" class="climax-map-choice" data-climax-action="${id}" aria-label="${label}を選ぶ"`:'';
 const situation=quest===1?`<p>レンは遠くの配達先に無事着き、水辺の村に住む家族へ手紙を出しました。ユノが集めた記録には、各地が手紙を送った時刻と次の場所が残っています。新しい札は「丘から水辺の村へ」と示しています。森からは丘へ戻れます。</p><svg class="climax-route" viewBox="0 0 520 220" role="group" aria-label="地図：港から丘、丘から森へ道があり、丘から水辺の村にも道がある。記録を選ぶと通った地点に色がつく"><path d="M55 110 L210 110 L380 48 M210 110 L380 170"/><g transform="translate(55 110)" ${mapAction('port','港')}>${mapChoice?'<circle class="climax-hit" r="39"/>':''}<circle class="${history.length>=1?'visited':''}" r="19"/><text y="46">港</text></g><g transform="translate(210 110)" ${mapAction('hill','丘の中継所')}>${mapChoice?'<circle class="climax-hit" r="39"/>':''}<circle class="${history.length>=1?'visited':''}" r="19"/><text y="46">丘の中継所</text></g><g transform="translate(380 48)" ${mapAction('forest','森')}>${mapChoice?'<circle class="climax-hit" r="39"/>':''}<circle class="${history.length>=3?'visited':''}" r="19"/><text x="-4" y="-27">森</text></g><g transform="translate(380 170)" ${mapAction('village','水辺の村')}>${mapChoice?'<circle class="climax-hit" r="39"/>':''}<circle r="19"/><text x="58" y="8">水辺の村</text></g></svg><p>記録：朝 港 → 丘 ／ 昼 丘 → 森（札に従う） ／ 夕 森に到着</p>`:quest===2?`<p>丘の中継所には荷車が一台。ハルはレンの手紙を含む急ぎの手紙を運ぶ準備ができ、メイはまだ荷物を準備しています。荷車は二人で同時には使えません。</p><div class="climax-map"><span>ハル：${history.length<6?'準備済み':history.length<7?'荷車で運搬中':'配達から戻った'}</span><span>荷車：${history.length<6?'空き':history.length<7?'ハルが使用中':history.length<8?'空き':'メイに渡した'}</span><span>メイ：${history.length<6?'準備中':'準備済み'}</span></div>`:`<p>レンの家族のもとに着きました。本人と配達側は、配達を頼んだときに秘密の合言葉を決めています。使いやすい方法と、合言葉を人に知られない場所を一緒に考えます。</p>`;
 app.innerHTML=`<section class="scene">${history.length===0?'<img src="./data/art/festival-city.png" alt="人々が集まる灯りの広場">':''}<h1>道と知らせをつなぐ集い</h1>${history.length===0?dialogue('lira','各地で起きた小さな行き違いが重なり、大切な手紙が届かなくなっているの。みんなと一緒に道をつなぎ直しましょう。'):''}${done?`<h2>手紙が届きました</h2><p>レンの家族は手紙を開き、何度も読み返しました。</p><blockquote>「無事に着いたのね。本当によかった。知らせてくれてありがとう」</blockquote>${dialogue('nono','届いたね！ みんなに知らせよう！')}<p>遠くにいるレンの知らせを、集まった各地の仲間が喜んでいます。</p>${storyRegions.filter(id=>id!=='harbor').map(id=>dialogue(...finalePeople[id])).join('')}${dialogue('lira','みんなの力で、大切な知らせが届いたわ。ありがとう。')}${dialogue('nono','あっ、まだ知らない土地からも知らせが来たよ！ 地図を広げてみよう！')}<p>新しい土地への道が開きます。冒険はこれからも続きます。</p><button id="climax-finish" class="primary">新しい旅先を見る</button>`:`<h2>${heading}</h2><p>依頼 ${quest} / 3</p>${dialogue(quest===1?'yuno':quest===2?'haru':'mizuho',quest===1?'記録と地図を並べたわ。一緒に手紙の通った道をたどりましょう。':quest===2?'荷車は一台だけ。二人の準備を見て、順番に運ぼう。':'本人に無理のない方法を聞いて、大切な手紙を渡そうね。')}<section class="panel"><h3>目標：${step.goal}</h3><p>${step.prompt}</p>${situation}${mapChoice?'<p>地図から地点を選びましょう。</p>':`<div class="actions">${step.choices.map(([id,label])=>`<button data-climax-action="${id}">${label}</button>`).join('')}</div>`}<details><summary>手がかりを聞く</summary><p>${step.hint}</p></details><p id="climax-status" role="status" tabindex="-1"></p></section><dialog id="success-dialog" class="story-success" aria-labelledby="climax-success-title"><h2 id="climax-success-title">依頼達成<span class="success-detail">${heading}</span></h2>${dialogue('nono','やったね！ みんなと一緒に、次へつなごう！')}<p>${lesson}</p><button id="climax-continue" class="primary">続きを見る</button></dialog>`}${warning()}<p><button id="finale-back">冒険へ戻る</button></p></section>`;
 app.querySelectorAll('[data-climax-action]').forEach(button=>button.onclick=()=>{const result=tryClimaxAction(history,button.dataset.climaxAction);if(!result.accepted){const status=app.querySelector('#climax-status');status.textContent=`もう一度考えてみましょう。${step.hint}`;status.focus({preventScroll:true});return;}state.storyClimaxHistory=result.history;persist();const next=climaxSteps[result.history.length];if(!next||next.quest!==quest){const dialog=app.querySelector('#success-dialog');dialog.addEventListener('cancel',event=>event.preventDefault());dialog.showModal();app.querySelector('#climax-continue').onclick=()=>{dialog.close();worldFinale();app.querySelector('h2')?.focus({preventScroll:true});};}else{worldFinale();app.querySelector('#climax-status')?.focus({preventScroll:true});}});
 app.querySelectorAll('.climax-map-choice').forEach(button=>button.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();button.dispatchEvent(new MouseEvent('click',{bubbles:true}));}}));
 app.querySelector('#climax-finish')?.addEventListener('click',()=>{state.storyClimaxComplete=true;persist();show('travel');});
 app.querySelector('#finale-back').onclick=()=>show(state.worldFinaleFrom??'choices');
}

function render(){
  const sideRegion=['new-quest','new-result'].includes(state?.place)?newEntrances[state?.newActive]?.region:null;
  const newRegion=fourRegionIds.includes(sideRegion)?sideRegion:fourRegionIds.includes(state?.place)?state.place:['four-quest','four-result'].includes(state?.place)?fourQuests[state?.fourActive]?.region:state?.place==='four-festival'?state?.fourFestivalFrom:null;
  const forgePlace=['forge','station','forge-station-quest','forge-station-result','forge-station-ending'].includes(state?.place),forgeRegion=state?.place==='forge'?'forge':state?.place==='station'||state?.place==='forge-station-ending'?'station':forgeStationQuests[state?.forgeStationActive]?.region;
  const towerPlace=['sky','mist','tower-gate-quest','tower-gate-result','tower-gate-ending'].includes(state?.place),towerRegion=state?.place==='sky'?'tower':state?.place==='mist'?'gate':towerGateQuests[state?.towerGateActive]?.region;
  const expansionRegion=expansionQuests[state?.expansionActive]?.region;const valleyPlace=state?.place?.startsWith('valley')||state?.place?.startsWith('expansion-')&&expansionRegion==='valley',expansionMountain=state?.place?.startsWith('expansion-')&&expansionRegion==='mountain',mountainPlace=state?.place?.startsWith('mountain')||expansionMountain,cityPlace=state?.place?.startsWith('city'),harborPlace=state?.place?.startsWith('harbor'),midPlace=state?.place?.startsWith('mid-');
  const midRegionName=state?.place==='mid-archive'?'archive':state?.place==='mid-windmill'?'windmill':state?.place==='mid-bridge'?state?.bridgeFrom:midQuests[state?.midActive]?.region;
  document.documentElement.dataset.region=state?.place==='world-finale'?'city':forgePlace?forgeRegion:towerPlace?(towerRegion==='gate'?'gate':'tower'):valleyPlace?'valley':mountainPlace?'mountain':midPlace?midRegionName:harborPlace?'harbor':cityPlace?'city':(state?.place==='river'||sideRegion==='river')||state?.activeQuest==='river'&&['encounter','journey-quest','journey-done'].includes(state?.place)?'river':'workshop';
  document.querySelector('header small').textContent=state?.place==='world-finale'?'灯花の街・広場':state?.place==='travel'?'旅の地図':newRegion?fourRegions[newRegion].name:forgePlace?(forgeRegion==='forge'?'星鉄の鍛冶街':'風待ちの駅'):towerPlace?(towerRegion==='gate'?'霧の関所':'空の中継塔'):valleyPlace?'谷の記録所':mountainPlace?'山の中継所':midPlace?(midRegionName==='archive'?'森の文庫':'風車の里'):harborPlace||sideRegion==='harbor'?'風の港町':cityPlace?'灯花の街':document.documentElement.dataset.region==='river'?'水辺の村':'はじまりの工房';
  if(state?.place==='archive-search-lab'){document.documentElement.dataset.region='archive';document.querySelector('header small').textContent='森の文庫';searchLab();return;}
  if(state?.place==='valley-query-lab'){document.documentElement.dataset.region='valley';document.querySelector('header small').textContent='谷の記録所';recordLab();return;}
  if(state?.place==='workshop-flower-lab'){document.documentElement.dataset.region='workshop';document.querySelector('header small').textContent='精霊の工房';flowerLab();return;}
  if(state?.place==='forge-swap-lab'){document.documentElement.dataset.region='forge';document.querySelector('header small').textContent='星鉄の鍛冶街';swapLab();return;}
  if(state?.place==='tower-name-lab'){document.documentElement.dataset.region='tower';document.querySelector('header small').textContent='空の中継塔';nameLab();return;}
  if(state?.place==='tower-queue-lab'){document.documentElement.dataset.region='tower';document.querySelector('header small').textContent='空の中継塔';queueLab();return;}
  if(state?.place==='gate-access-lab'){document.documentElement.dataset.region='gate';document.querySelector('header small').textContent='霧の関所';accessLab();return;}
  if(state?.place==='gate-paths-lab'){document.documentElement.dataset.region='gate';document.querySelector('header small').textContent='霧の関所';pathsLab();return;}
  if(state?.place==='valley-tables-lab'){document.documentElement.dataset.region='valley';document.querySelector('header small').textContent='谷の記録所';tablesLab();return;}
  if(state?.place==='valley-integrity-lab'){document.documentElement.dataset.region='valley';document.querySelector('header small').textContent='谷の記録所';integrityLab();return;}
  if(state?.place==='station-schedule-lab'){document.documentElement.dataset.region='station';document.querySelector('header small').textContent='風待ちの駅';schedulingLab();return;}
  if(state?.place==='forge-pages-lab'){document.documentElement.dataset.region='forge';document.querySelector('header small').textContent='星鉄の鍛冶街';pagesLab();return;}
  if(['guide-accessibility-lab','guide-usability-lab'].includes(state?.place)){document.documentElement.dataset.region='guide';document.querySelector('header small').textContent=fourRegions.guide.name;guideLab(state.place==='guide-accessibility-lab');return;}
  if(['observatory-forecast-lab','observatory-errors-lab'].includes(state?.place)){document.documentElement.dataset.region='observatory';document.querySelector('header small').textContent=fourRegions.observatory.name;forecastLab(state.place==='observatory-errors-lab');return;}
  if(['river-type-tools','river-type-record','river-type-branch'].includes(state?.place)){document.documentElement.dataset.region='river';document.querySelector('header small').textContent='水辺の村';typeLab(state.place);return;}
  if(['garden-image-fit','garden-image-pixels'].includes(state?.place)){document.documentElement.dataset.region='garden';document.querySelector('header small').textContent=fourRegions.garden.name;imageLab(state.place==='garden-image-pixels');return;}
  if(state?.place==='garden-image-resample'){document.documentElement.dataset.region='garden';document.querySelector('header small').textContent=fourRegions.garden.name;resampleLab();return;}
  if(['harbor-count','harbor-join','harbor-lock'].includes(state?.place)){document.documentElement.dataset.region='harbor';document.querySelector('header small').textContent='風の港町';cooperationLab(state.place);return;}
  if(!state){title();return;}if(fourRegionIds.includes(state.place))fourRegion(state.place);else if(state.place==='four-quest')fourQuest();else if(state.place==='four-result')fourResult();else if(state.place==='four-festival')fourFestival();else if(state.place==='world-finale')worldFinale();else if(state.place==='new-quest')newQuest();else if(state.place==='new-result')newResult();else if(state.place==='world')world();else if(state.place==='introduction')introduction();else if(state.place==='quest')quest();else if(state.place==='opening-done')openingDone();else if(state.place==='outside')forestEncounter();else if(state.place==='forest-quest')forestQuest();else if(state.place==='forest-done')forestDone();else if(state.place==='encounter')encounter();else if(state.place==='journey-quest')journeyQuest();else if(state.place==='journey-done')journeyDone();else if(state.place==='travel')travel();else if(state.place==='river')river();else if(state.place==='city')city();else if(state.place==='city-guild'||state.place==='city-market')cityPerson(state.place);else if(state.place==='city-quest')cityQuest();else if(state.place==='city-result')cityResult();else if(state.place==='city-festival')cityFestival();else if(state.place==='harbor')harbor();else if(state.place==='harbor-quest')harborQuest();else if(state.place==='harbor-result')harborResult();else if(state.place==='mid-archive')midRegion('archive');else if(state.place==='mid-windmill')midRegion('windmill');else if(state.place==='mid-quest')midQuest();else if(state.place==='mid-result')midResult();else if(state.place==='mid-bridge')midBridge();else if(state.place==='mountain')mountainRegion();else if(state.place==='mountain-quest')mountainQuest();else if(state.place==='mountain-result')mountainResult();else if(state.place==='mountain-ending')mountainEnding();else if(state.place==='mountain-crossing')mountainCrossing();else if(state.place==='forge'||state.place==='station')forgeStationRegion(state.place);else if(state.place==='forge-station-quest')forgeStationQuest();else if(state.place==='forge-station-result')forgeStationResult();else if(state.place==='forge-station-ending')forgeStationEnding();else if(state.place==='sky'||state.place==='mist')towerGateRegion(state.place);else if(state.place==='tower-gate-quest')towerGateQuest();else if(state.place==='tower-gate-result')towerGateResult();else if(state.place==='tower-gate-ending')towerGateEnding();else if(state.place==='valley')valleyRegion();else if(state.place==='valley-ending')valleyEnding();else if(state.place==='expansion-quest')expansionQuest();else if(state.place==='expansion-result')expansionResult();else choices();
  finaleNotice();
}
applySettings();if(saveProtected)error='以前の体験版の記録を読み込めません。元の記録を保護します。';title();
